arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) printf '%s\n' "x-access-token" ;;
  *) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git -C /tmp/wt-chandler push origin HEAD:refs/heads/friend/chandler 2>&1 | tail -5
